import java.util.ArrayList;
import java.util.List;

public class BoxUtils {

    public static <T extends Comparable<T>> Box<T> maxOf(List<Box<T>> boxes) {
        Box<T> best = new Box<T>();
        for (Box<T> box : boxes) {
            if (box.isEmpty()) {
                continue;
            }
            if (best.isEmpty() || box.get().compareTo(best.get()) > 0) {
                best.set(box.get());
            }
        }
        return best;
    }

    public static <T> List<T> unwrap(List<Box<T>> boxes) {
        List<T> values = new ArrayList<T>();
        for (Box<T> box : boxes) {
            if (!box.isEmpty()) {
                values.add(box.get());
            }
        }
        return values;
    }
}

