import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class BoxUtilsTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Box<String> fresh = new Box<String>();
        check("a new box is empty", true, fresh.isEmpty());
        check("a new box holds null", null, fresh.get());
        fresh.set("hi");
        check("after set the box is not empty", false, fresh.isEmpty());
        check("after set the box returns the value", "hi", fresh.get());
        fresh.set(null);
        check("setting null empties the box again", true, fresh.isEmpty());

        Box<Integer> made = Box.of(41);
        check("Box.of stores the value", 41, made.get());
        check("Box.of is not empty", false, made.isEmpty());
        int unboxedSum = 0;
        try {
            unboxedSum = Box.of(3).get() + 1;
        } catch (RuntimeException e) {
            System.out.println("FAIL  Box.of(3).get() + 1 -- threw " + e);
            failures++;
        }
        check("get() returns T, so no cast is needed", 4, unboxedSum);

        List<Box<String>> words = new ArrayList<Box<String>>();
        words.add(Box.of("fig"));
        words.add(new Box<String>());
        words.add(Box.of("kiwi"));
        words.add(Box.of("apple"));
        check("maxOf picks the largest String", "kiwi", BoxUtils.maxOf(words).get());
        check("unwrap skips the empty box", "[fig, kiwi, apple]", String.valueOf(BoxUtils.unwrap(words)));

        List<Box<Integer>> numbers = Arrays.asList(new Box<Integer>(), Box.of(12), Box.of(-4), new Box<Integer>(), Box.of(7));
        check("maxOf picks the largest Integer", 12, BoxUtils.maxOf(numbers).get());
        check("unwrap keeps the original order", "[12, -4, 7]", String.valueOf(BoxUtils.unwrap(numbers)));

        List<Box<String>> allEmpty = Arrays.asList(new Box<String>(), new Box<String>());
        Box<String> noMax = BoxUtils.maxOf(allEmpty);
        check("maxOf of only-empty boxes is not null", true, noMax != null);
        check("maxOf of only-empty boxes is an empty box", true, noMax == null || noMax.isEmpty());
        check("unwrap of only-empty boxes", "[]", String.valueOf(BoxUtils.unwrap(allEmpty)));

        List<Box<String>> none = new ArrayList<Box<String>>();
        Box<String> emptyMax = BoxUtils.maxOf(none);
        check("maxOf of an empty list is an empty box", true, emptyMax != null && emptyMax.isEmpty());
        check("unwrap of an empty list", "[]", String.valueOf(BoxUtils.unwrap(none)));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

